INSERT INTO plugin_data.csf_profile_link_requests(id,organization_id,cohort_id,user_id,first_name,last_name,normalized_first_name,normalized_last_name,match_status,matched_profile_id)
VALUES('fd180000-0000-4000-8000-000000000001','fd110000-0000-4000-8000-000000000001','fd130000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002','Fictional','Student1','fictional','student1','auto_linked','fd140000-0000-4000-8000-000000000001');
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
SELECT extensions.ok(NOT has_function_privilege('anon','plugin_data.csf_review_profile_account_ownership(uuid,uuid,uuid,text,text,uuid,uuid,uuid)','EXECUTE'),'anon execution privilege is correct');
SELECT extensions.ok(NOT has_function_privilege('authenticated','plugin_data.csf_review_profile_account_ownership(uuid,uuid,uuid,text,text,uuid,uuid,uuid)','EXECUTE'),'authenticated execution privilege is correct');
SELECT extensions.ok(has_function_privilege('service_role','plugin_data.csf_review_profile_account_ownership(uuid,uuid,uuid,text,text,uuid,uuid,uuid)','EXECUTE'),'service_role execution privilege is correct');
SELECT extensions.throws_ok($q$SELECT plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002','connect-target@local.test','Officer verified the name and class.','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')$q$,'42501',NULL,'member cannot approve ownership');
SELECT extensions.throws_ok($q$SELECT plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000004','fd100000-0000-4000-8000-000000000001','connect-target@local.test','Officer verified the name and class.','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')$q$,'P0001',NULL,'cross organization profile refused');
SELECT extensions.throws_ok($q$SELECT plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000002','fd100000-0000-4000-8000-000000000001','connect-target@local.test','Officer verified the name and class.','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')$q$,'P0001',NULL,'different profile cannot replace existing link');
SELECT extensions.throws_ok($q$SELECT plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','connect-target@local.test','Officer verified the name and class.','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000006')$q$,'P0001',NULL,'different user cannot replace existing owner');
SELECT extensions.throws_ok($q$SELECT plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','stale@local.test','Officer verified the name and class.','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')$q$,'P0001',NULL,'stale login refused');
SELECT extensions.throws_ok($q$SELECT plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','connect-target@local.test','short','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')$q$,'P0001',NULL,'short reason refused');
UPDATE auth.users SET email_confirmed_at=NULL WHERE id='fd100000-0000-4000-8000-000000000002';
SELECT extensions.throws_ok($q$SELECT plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','connect-target@local.test','Officer verified the name and class.','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')$q$,'P0001',NULL,'unconfirmed login refused');
UPDATE auth.users SET email_confirmed_at=now() WHERE id='fd100000-0000-4000-8000-000000000002';
UPDATE public.organization_members SET status='inactive' WHERE user_id='fd100000-0000-4000-8000-000000000002';
SELECT extensions.throws_ok($q$SELECT plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','connect-target@local.test','Officer verified the name and class.','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')$q$,'P0001',NULL,'inactive membership refused');
UPDATE public.organization_members SET status='active' WHERE user_id='fd100000-0000-4000-8000-000000000002';
UPDATE plugin_data.csf_profile_cohort_memberships SET status='archived' WHERE profile_id='fd140000-0000-4000-8000-000000000001';
SELECT extensions.throws_ok($q$SELECT plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','connect-target@local.test','Officer verified the name and class.','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')$q$,'P0001',NULL,'missing active class refused');
UPDATE plugin_data.csf_profile_cohort_memberships SET status='active' WHERE profile_id='fd140000-0000-4000-8000-000000000001';
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
SELECT extensions.lives_ok($q$SELECT plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','connect-target@local.test','Officer verified the name and class.','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')$q$,'staff can review an existing link with a different imported contact');
SET CONSTRAINTS ALL IMMEDIATE;
SELECT extensions.ok((SELECT connection_basis='officer_decision' AND linked_at='2024-09-01'::timestamptz AND notes='Original historical import' AND linked_by IS NULL AND user_id='fd100000-0000-4000-8000-000000000002' AND profile_id='fd140000-0000-4000-8000-000000000001' FROM plugin_data.csf_profile_accounts WHERE id='fd170000-0000-4000-8000-000000000001'),'review preserves the original link identity and provenance');
SELECT extensions.is((SELECT personal_email FROM plugin_data.csf_profiles WHERE id='fd140000-0000-4000-8000-000000000001'),'source1@local.test','imported contact is preserved');
SELECT extensions.is((SELECT match_status FROM plugin_data.csf_profile_link_requests WHERE id='fd180000-0000-4000-8000-000000000001'),'resolved','matching legacy request resolves atomically');
SELECT extensions.is((SELECT count(*)::int FROM plugin_data.csf_publication_events WHERE organization_id='fd110000-0000-4000-8000-000000000001' AND event_key LIKE 'account_connected:%'),1,'one account notice is queued');
SELECT extensions.ok((plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','connect-target@local.test','Officer verified the name and class.','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')->>'replayed')::boolean,'same request replays');
SELECT extensions.ok((plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','connect-target@local.test','Officer verified the name and class.','fd190000-0000-4000-8000-000000000002','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')->>'alreadyReviewed')::boolean,'new request for reviewed link is a no-op');
SELECT extensions.throws_ok($q$SELECT plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','connect-target@local.test','A different verification reason.','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')$q$,'P0001',NULL,'changed reason cannot reuse receipt');
SELECT extensions.is((SELECT count(*)::int FROM plugin_data.csf_admin_audit_events WHERE organization_id='fd110000-0000-4000-8000-000000000001' AND action='profile.account_ownership_reviewed'),1,'retries retain one ownership audit');
SELECT extensions.ok((SELECT before_data->>'connection_basis'='unknown' AND after_data->>'connection_basis'='officer_decision' AND after_data->>'reason'='Officer verified the name and class.' FROM plugin_data.csf_admin_audit_events WHERE organization_id='fd110000-0000-4000-8000-000000000001' AND action='profile.account_ownership_reviewed'),'audit records original basis and staff reason');
SELECT extensions.is((SELECT count(*)::int FROM plugin_data.csf_publication_events WHERE organization_id='fd110000-0000-4000-8000-000000000001' AND event_key LIKE 'account_connected:%'),1,'retries do not duplicate the notice');
SELECT extensions.is((SELECT count(*)::int FROM plugin_data.csf_publication_notification_deliveries d JOIN plugin_data.csf_publication_events e ON e.id=d.event_id WHERE e.organization_id='fd110000-0000-4000-8000-000000000001' AND e.event_key LIKE 'account_connected:%'),1,'one delivery belongs to the reviewed account');
SELECT extensions.ok(NOT EXISTS(SELECT 1 FROM plugin_data.csf_term_memberships WHERE organization_id='fd110000-0000-4000-8000-000000000001') AND NOT EXISTS(SELECT 1 FROM plugin_data.csf_credit_records WHERE organization_id='fd110000-0000-4000-8000-000000000001'),'review grants no semester membership or credits');
UPDATE plugin_data.csf_profile_accounts SET status='revoked',is_primary=false,revoked_at=now() WHERE id='fd170000-0000-4000-8000-000000000001';
SELECT extensions.throws_ok($q$SELECT plugin_data.csf_review_profile_account_ownership('fd110000-0000-4000-8000-000000000001','fd140000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000001','connect-target@local.test','Officer verified the name and class.','fd190000-0000-4000-8000-000000000001','fd170000-0000-4000-8000-000000000001','fd100000-0000-4000-8000-000000000002')$q$,'P0001',NULL,'retry refuses a revoked connection');
SELECT * FROM extensions.finish();
ROLLBACK;
